+// collectCommitsSince returns commits on the ancestry path from stopAt
+// (exclusive) to tip (inclusive), ordered oldest-first.
+func collectCommitsSince(ctx context.Context, repo *git.Repository, repoPath string, tip, stopAt plumbing.Hash) ([]*object.Commit, error) {
+	ctx, cancel := context.WithTimeout(ctx, 10*time.Second)
+	defer cancel()
+
+	cmd := exec.CommandContext(ctx, "git", "rev-list", "--reverse", "--ancestry-path", stopAt.String()+".."+tip.String())
+	cmd.Dir = repoPath
+	output, err := cmd.Output()
+	if err != nil {
+		return nil, fmt.Errorf("git rev-list failed: %w", err)
+	}
+
+	lines := strings.Fields(string(output))
+	if len(lines) > MaxCommitTraversalDepth {
+		return nil, fmt.Errorf("commit chain exceeded %d commits; aborting rebase", MaxCommitTraversalDepth)
